import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"apache2 Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"apache2","tag":"apache2","title":"apache2 Tag","prev":null,"next":null,"posts":[{"title":"Ubuntu下apache2的配置记录","url":"/posts/2013-06-06-ubuntu-config-apache2/","date":"2013-06-06 21:41","tags":["linux","apache2"],"html":"<p>自从 2012 年四月买 VPS...到现在已经算是一年多了吧.在此感谢琴对我的帮助和指导.没有琴的指导我也不会折腾和配置 VPS.\\n期间一点一点的成长都离不开大家的帮助.不过对琴的过度依赖,使我一度成为伸手党...真是十分抱歉 QAQ\\n现在写一篇日志记录下 apache2 的配置方法也可以留着自己以后进行参考.</p>\\n<h2 id=\\"安装-apache-套装\\" tabindex=\\"-1\\">安装 apache 套装 <a class=\\"header-anchor\\" href=\\"#安装-apache-套装\\" aria-label=\\"Permalink to &quot;安装 apache 套装&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先安装 lamp<code>sudo apt-get install lamp-server^</code>PHP 开发和服务器运行环境首选 LAMP 组合，即 Linux+Apache+Mysql+Php/Perl/Python，能最优化服务器性能</p>\\n<h2 id=\\"开启相关模块\\" tabindex=\\"-1\\">开启相关模块 <a class=\\"header-anchor\\" href=\\"#开启相关模块\\" aria-label=\\"Permalink to &quot;开启相关模块&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>启用 mod_rewrite 模块</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> a2enmod</span><span style=\\"color:#032F62\\"> rewrite</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>启用 mod_proxy 模块</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> a2enmod</span><span style=\\"color:#032F62\\"> proxy</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> a2enmod</span><span style=\\"color:#032F62\\"> proxy_http</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>启用 SSL 模块</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> a2enmod</span><span style=\\"color:#032F62\\"> ssl</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>a2xx 系列的命令共有 a2dismod、a2enmod、a2dissite、a2ensite，作用分别是禁用模块、启用模块、停用站点、启用站点这些命令简单得连--help 选项都没有，只能运行看提示。其作用也很简单，就是在/etc/apache2/mods-enabled 和/etc/apache2/sites-enabled 里面建立或删除相对应的 x-available 目录里面的模块的链接。</p>\\n<h2 id=\\"具体相关配置\\" tabindex=\\"-1\\">具体相关配置 <a class=\\"header-anchor\\" href=\\"#具体相关配置\\" aria-label=\\"Permalink to &quot;具体相关配置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>服务器资源一般很高贵,大家都会挂很多独立站点的.apache2 默认存放网站的目录是 /var/www\\n配置文件储存在 /etc/apache2 主配置文件在 apache2.conf 其中这个配置文件包含了 sites-enabled 目录\\n这个目录是主要储存配置文件的地方 配置文件以 000-default 000-default-ssl 这种命名方式进行命名.\\n这两个文件是对 http 和 https 进行默认配置.下面我们来看看这两个默认配置\\nvim 000-default</p>\\n<div class=\\"language-apacheconf line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">apacheconf</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">VirtualHost</span><span style=\\"color:#032F62\\"> *:80</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ServerAdmin</span><span style=\\"color:#24292E\\"> acgotaku311@email.me</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    ServerName</span><span style=\\"color:#24292E\\"> _default_</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">DocumentRoot</span><span style=\\"color:#24292E\\"> /var/www/default</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> /</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Options</span><span style=\\"color:#24292E\\"> FollowSymLinks</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  AllowOverride</span><span style=\\"color:#24292E\\"> None</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> /var/www/default</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Options</span><span style=\\"color:#24292E\\"> Indexes FollowSymLinks MultiViews</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  AllowOverride</span><span style=\\"color:#24292E\\"> None</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Order</span><span style=\\"color:#24292E\\"> allow,deny</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  allow </span><span style=\\"color:#6F42C1\\">from</span><span style=\\"color:#24292E\\"> all</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ScriptAlias</span><span style=\\"color:#032F62\\"> /cgi-bin/</span><span style=\\"color:#032F62\\"> /usr/lib/cgi-bin/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> \\"/usr/lib/cgi-bin\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  AllowOverride</span><span style=\\"color:#24292E\\"> None</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Options</span><span style=\\"color:#24292E\\"> +ExecCGI -MultiViews +SymLinksIfOwnerMatch</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Order</span><span style=\\"color:#24292E\\"> allow,deny</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Allow</span><span style=\\"color:#6F42C1\\"> from</span><span style=\\"color:#24292E\\"> all</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ErrorLog</span><span style=\\"color:#24292E\\"> ${APACHE_LOG_DIR}/error.log</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># Possible values include: debug, info, notice, warn, error, crit,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># alert, emerg.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">LogLevel</span><span style=\\"color:#24292E\\"> warn</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">CustomLog</span><span style=\\"color:#24292E\\"> ${APACHE_LOG_DIR}/access.log combined</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">Alias</span><span style=\\"color:#032F62\\"> /doc/</span><span style=\\"color:#032F62\\"> \\"/usr/share/doc/\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> \\"/usr/share/doc/\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    Options</span><span style=\\"color:#24292E\\"> Indexes MultiViews FollowSymLinks</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    AllowOverride</span><span style=\\"color:#24292E\\"> None</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    Order</span><span style=\\"color:#24292E\\"> deny,allow</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    Deny</span><span style=\\"color:#6F42C1\\"> from</span><span style=\\"color:#24292E\\"> all</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    Allow</span><span style=\\"color:#6F42C1\\"> from</span><span style=\\"color:#005CC5\\"> 127</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">/</span><span style=\\"color:#005CC5\\">255</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\"> ::</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">/</span><span style=\\"color:#005CC5\\">128</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">VirtualHost</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br></div></div><p>第一行指定的是服务使用的端口. 第二行 ServerAdmin 写的是服务器管理员的邮箱.\\n第三行 <code>ServerName</code> 写的是服务器的名字 <code>_default_</code> 代表默认使用这个, 即服务器名字找不到对应的配置文件的时候使用此配置文件.\\n第四行 <code>DocumentRoot</code> 写的是网站的根目录,即输入网址映射到服务器具体的哪个站点.\\n<code>Directory</code> 子节点是对具体目录进行配置 我们主要是对网站根目录进行权限的配置.\\n其中主要说明的是 <code>AllowOverride</code> 选项 <code>AllowOverride</code> 控制那些被放置在 <code>.htaccess</code> 文件中的指令.\\n其余的配置基本不需要关心, <code>vim 000-default-ssl</code></p>\\n<div class=\\"language-apacheconf line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">apacheconf</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IfModule</span><span style=\\"color:#032F62\\"> mod_ssl.c</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">VirtualHost</span><span style=\\"color:#032F62\\"> *:443</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ServerAdmin</span><span style=\\"color:#24292E\\"> acgotaku311@email.me</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    ServerName</span><span style=\\"color:#24292E\\">  _default_</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">DocumentRoot</span><span style=\\"color:#24292E\\"> /var/www/default</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> /</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Options</span><span style=\\"color:#24292E\\"> FollowSymLinks</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  AllowOverride</span><span style=\\"color:#24292E\\"> None</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> /var/www/default</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Options</span><span style=\\"color:#24292E\\"> Indexes FollowSymLinks MultiViews</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  AllowOverride</span><span style=\\"color:#24292E\\"> All</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Order</span><span style=\\"color:#24292E\\"> allow,deny</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  allow </span><span style=\\"color:#6F42C1\\">from</span><span style=\\"color:#24292E\\"> all</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ScriptAlias</span><span style=\\"color:#032F62\\"> /cgi-bin/</span><span style=\\"color:#032F62\\"> /usr/lib/cgi-bin/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> \\"/usr/lib/cgi-bin\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  AllowOverride</span><span style=\\"color:#24292E\\"> None</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Options</span><span style=\\"color:#24292E\\"> +ExecCGI -MultiViews +SymLinksIfOwnerMatch</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Order</span><span style=\\"color:#24292E\\"> allow,deny</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Allow</span><span style=\\"color:#6F42C1\\"> from</span><span style=\\"color:#24292E\\"> all</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ErrorLog</span><span style=\\"color:#24292E\\"> ${APACHE_LOG_DIR}/error.log</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># Possible values include: debug, info, notice, warn, error, crit,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># alert, emerg.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">LogLevel</span><span style=\\"color:#24292E\\"> warn</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">CustomLog</span><span style=\\"color:#24292E\\"> ${APACHE_LOG_DIR}/ssl_access.log combined</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">Alias</span><span style=\\"color:#032F62\\"> /doc/</span><span style=\\"color:#032F62\\"> \\"/usr/share/doc/\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> \\"/usr/share/doc/\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Options</span><span style=\\"color:#24292E\\"> Indexes MultiViews FollowSymLinks</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  AllowOverride</span><span style=\\"color:#24292E\\"> None</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Order</span><span style=\\"color:#24292E\\"> deny,allow</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Deny</span><span style=\\"color:#6F42C1\\"> from</span><span style=\\"color:#24292E\\"> all</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  Allow</span><span style=\\"color:#6F42C1\\"> from</span><span style=\\"color:#005CC5\\"> 127</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">/</span><span style=\\"color:#005CC5\\">255</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\"> ::</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">/</span><span style=\\"color:#005CC5\\">128</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">#   SSL Engine Switch:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">#   Enable/Disable SSL for this virtual host.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">SSLEngine</span><span style=\\"color:#6F42C1\\"> on</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">SSLCertificateFile</span><span style=\\"color:#24292E\\">    /etc/apache2/ssl/ssl.crt</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">SSLCertificateKeyFile</span><span style=\\"color:#24292E\\"> /etc/apache2/ssl/ssl.key</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">FilesMatch</span><span style=\\"color:#032F62\\"> \\"\\\\.(cgi|shtml|phtml|php)$\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  SSLOptions</span><span style=\\"color:#24292E\\"> +StdEnvVars</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">FilesMatch</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#032F62\\"> /usr/lib/cgi-bin</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  SSLOptions</span><span style=\\"color:#24292E\\"> +StdEnvVars</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">Directory</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">BrowserMatch</span><span style=\\"color:#24292E\\"> \\"MSIE [</span><span style=\\"color:#005CC5\\">17</span><span style=\\"color:#24292E\\">-</span><span style=\\"color:#005CC5\\">9</span><span style=\\"color:#24292E\\">]\\" ssl-unclean-shutdown</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">VirtualHost</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#6F42C1\\">IfModule</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br></div></div><p>SSL 模块就是多了一个证书的设置, 其余的基本不变.</p>\\n<p>其它站点基本就是拷贝默认的配置文件修改 ServerName 和 DocumentRoot 即可.</p>\\n<h2 id=\\"关于-ssl-证书\\" tabindex=\\"-1\\">关于 SSL 证书 <a class=\\"header-anchor\\" href=\\"#关于-ssl-证书\\" aria-label=\\"Permalink to &quot;关于 SSL 证书&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>生成 SSl 证书命令</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">openssl</span><span style=\\"color:#032F62\\"> genrsa</span><span style=\\"color:#005CC5\\"> -des3</span><span style=\\"color:#005CC5\\"> -out</span><span style=\\"color:#032F62\\"> ssl.key</span><span style=\\"color:#005CC5\\"> 1024</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后他会要求你输入这个 key 文件的密码。不推荐输入。 但是生成时候必须输入密码。你可以输入后 再删掉。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">mv</span><span style=\\"color:#032F62\\"> ssl.key</span><span style=\\"color:#032F62\\"> xxx.key</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">openssl</span><span style=\\"color:#032F62\\"> rsa</span><span style=\\"color:#005CC5\\"> -in</span><span style=\\"color:#032F62\\"> xxx.key</span><span style=\\"color:#005CC5\\"> -out</span><span style=\\"color:#032F62\\"> ssl.key</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">rm</span><span style=\\"color:#032F62\\"> xxx.key</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>然后根据这个 key 文件生成证书请求文件<code>openssl req -new -key ssl.key -out ssl.csr</code>以上命令生成时候要填很多东西 一个个看着写吧（可以随便，毕竟这是自己生成的证书）最后根据这 2 个文件生成 crt 证书文件</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">openssl</span><span style=\\"color:#032F62\\"> x509</span><span style=\\"color:#005CC5\\"> -req</span><span style=\\"color:#005CC5\\"> -days</span><span style=\\"color:#005CC5\\"> 365</span><span style=\\"color:#005CC5\\"> -in</span><span style=\\"color:#032F62\\"> ssl.csr</span><span style=\\"color:#005CC5\\"> -signkey</span><span style=\\"color:#032F62\\"> ssl.key</span><span style=\\"color:#005CC5\\"> -out</span><span style=\\"color:#032F62\\"> ssl.crt</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这里 365 是证书有效期 推荐 3650 哈哈。这个大家随意。最后使用到的文件是 key 和 crt 文件。</p>\\n<p>这里生成的证书是不受信任的...我们可以在<a href=\\"https://letsencrypt.org/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Let\'s Encrypt</a>上申请免费的证书.</p>\\n"}]},"relativePath":"tags/apache2/index.md","filePath":"tags/[slug].md"}'),l={name:"tags/apache2/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const u=s(l,[["render",p]]);export{b as __pageData,u as default};
